def _leg(res, recall_bar):
    """One leg's three-valued verdict from a score_arm result."""
    if res is None:
        return False
    numerator, denominator = Decimal(str(recall_bar)).as_integer_ratio()
    meets_recall = (res["gold_n"] > 0
                    and res["matched"] * denominator >= res["gold_n"] * numerator)
    hard_fail = (res.get("wrong_lane", 0) > 0
                 or res["would_park"] > 0.10 or res["value_shape_acc"] < 0.98
                 or not meets_recall and res["PASS"] is False)
    if res["PASS"] is None:
        # pending verdicts/ties — but a known failure takes priority over None
        if not meets_recall and res["PASS"] is False:
            return False
        if hard_fail and meets_recall:
            return False
        if meets_recall and not hard_fail:
            return None                    # could still turn True
        return False if res["PASS"] is False else (
            None if meets_recall else False)
    if not res["PASS"] and meets_recall:
        return False
    if res["PASS"] and meets_recall:
        return True
    return False

